// Oracle-only stand-in for `@earendil-works/pi-ai/compat`. Upstream
// `completeSimple` routes through the provider registry; the oracle always
// supplies a scripted `streamFn`, so this default transport is unreachable.
// If it is ever hit the capture must be treated as invalid.
export function completeSimple() {
  throw new Error("oracle: completeSimple must not be called (pass streamFn)");
}
